  6	__device__ __forceinline__ float bits_to_float(uint32_t bits) {
  7	    union {
  8	        uint32_t u;
  9	        float f;
 10	    } v;
 11	    v.u = bits;
 12	    return v.f;
 13	}
 14	
 15	__device__ __forceinline__ uint32_t float_to_bits(float x) {
 16	    union {
 17	        float f;
 18	        uint32_t u;
 19	    } v;
 20	    v.f = x;
 21	    return v.u;
 22	}
 23	
 24	__device__ __forceinline__ float pow2_int(int exp) {
 25	    if (exp >= -126) {
 26	        return bits_to_float(static_cast<uint32_t>(exp + 127) << 23);
 27	    }
 28	    return bits_to_float(0x00400000u); // 2^-127, used for the all-zero scale.
 29	}
 30	
 31	__device__ __forceinline__ float fp16_abs_to_float(uint16_t x) {
 32	    const uint32_t exp = (x >> 10) & 0x1fu;
 33	    const uint32_t mant = x & 0x03ffu;
 34	    if (exp == 0) {
 35	        return 0.0f;
 36	    }
 37	    return bits_to_float(((exp + (127u - 15u)) << 23) | (mant << 13));
 38	}
 39	
 40	__device__ __forceinline__ float bf16_abs_to_float(uint16_t x) {
 41	    return bits_to_float(static_cast<uint32_t>(x & 0x7fffu) << 16);
 42	}
 43	
 44	__device__ __forceinline__ uint8_t scale_byte_from_amax(float amax) {
 45	    const uint32_t r_bits = (float_to_bits(amax) + 0x00200000u) & 0x7f800000u;
 46	    int exponent = -127;
 47	    if (r_bits != 0) {
 48	        exponent = static_cast<int>(r_bits >> 23) - 129;
 49	        exponent = exponent < -127 ? -127 : exponent;
 50	        exponent = exponent > 127 ? 127 : exponent;
 51	    }
 52	    return static_cast<uint8_t>(exponent + 127);
 53	}
 54	
 55	__device__ __forceinline__ uint8_t quantize_e2m1_even(float scaled_abs, bool negative) {
 56	    uint8_t code;
 57	    if (scaled_abs <= 0.25f) {
 58	        code = 0;
 59	    } else if (scaled_abs < 0.75f) {
 60	        code = 1;
 61	    } else if (scaled_abs <= 1.25f) {
 62	        code = 2;
 63	    } else if (scaled_abs < 1.75f) {
 64	        code = 3;
 65	    } else if (scaled_abs <= 2.5f) {
 66	        code = 4;
 67	    } else if (scaled_abs < 3.5f) {
 68	        code = 5;
 69	    } else if (scaled_abs <= 5.0f) {
 70	        code = 6;
 71	    } else {
 72	        code = 7;
 73	    }
 74	    return negative ? static_cast<uint8_t>(code | 0x8u) : code;
 75	}
 76	
 77	template <int DType>
 78	__global__ __launch_bounds__(256) void quant_mxfp4_even_kernel(
 79	    const uint16_t* __restrict__ input,
 80	    uint8_t* __restrict__ packed_output,
 81	    uint8_t* __restrict__ scale_output,
 82	    int64_t num_groups) {
 83	    constexpr int groups_per_block = 8;
 84	    const int tid = static_cast<int>(threadIdx.x);
 85	    const int lane_in_group = tid & 31;
 86	    const int group_in_block = tid >> 5;
 87	    const int64_t group = static_cast<int64_t>(blockIdx.x) * groups_per_block + group_in_block;
 88	
 89	    float abs_x = 0.0f;
 90	    bool negative = false;
 91	    if (group < num_groups) {
 92	        const uint16_t raw = input[group * 32 + lane_in_group];
 93	        negative = (raw & 0x8000u) != 0;
 94	        const uint16_t abs_raw = static_cast<uint16_t>(raw & 0x7fffu);
 95	        if constexpr (DType == 0) {
 96	            abs_x = fp16_abs_to_float(abs_raw);
 97	        } else {
 98	            abs_x = bf16_abs_to_float(abs_raw);
 99	        }
100	    }
101	
102	    float amax = abs_x;
103	    amax = fmaxf(amax, __shfl_xor(amax, 16));
104	    amax = fmaxf(amax, __shfl_xor(amax, 8));
105	    amax = fmaxf(amax, __shfl_xor(amax, 4));
106	    amax = fmaxf(amax, __shfl_xor(amax, 2));
107	    amax = fmaxf(amax, __shfl_xor(amax, 1));
108	
109	    const uint8_t scale_byte = scale_byte_from_amax(amax);
110	    const int exponent = static_cast<int>(scale_byte) - 127;
111	    const float scaled_abs = abs_x * pow2_int(-exponent);
112	    const uint8_t nibble = quantize_e2m1_even(scaled_abs, negative);
113	
114	    if (group < num_groups) {
115	        if (lane_in_group == 0) {
116	            scale_output[group] = scale_byte;
117	        }
118	        if ((lane_in_group & 1) == 0) {
119	            const uint8_t hi = static_cast<uint8_t>(__shfl_down(static_cast<unsigned int>(nibble), 1));
120	            packed_output[group * 16 + (lane_in_group >> 1)] = static_cast<uint8_t>(nibble | (hi << 4));
121	        }
122	    }
123	}
