127	// dtype: 0 = FP16, 1 = BF16. Pointers address distinct device buffers.
128	// Enqueue on stream and return a hipError_t integer; do not synchronize.
129	extern "C" int aiter_rs_quant_mxfp4_even(
130	    const void* input,
131	    void* packed_output,
132	    void* scale_output,
133	    int64_t rows,
134	    int64_t cols,
135	    int dtype,
136	    void* stream) {
137	    if (input == nullptr || packed_output == nullptr || scale_output == nullptr ||
138	        rows <= 0 || cols <= 0 || (cols & 31) != 0) {
139	        return static_cast<int>(hipErrorInvalidValue);
140	    }
141	
142	    const int64_t num_groups = rows * (cols >> 5);
143	    const dim3 block(256);
144	    const dim3 grid(static_cast<unsigned int>((num_groups + 7) >> 3));
145	    hipStream_t hip_stream = reinterpret_cast<hipStream_t>(stream);
146	
147	    if (dtype == 0) {
148	        hipLaunchKernelGGL((quant_mxfp4_even_kernel<0>), grid, block, 0, hip_stream,
149	                           static_cast<const uint16_t*>(input),
150	                           static_cast<uint8_t*>(packed_output),
151	                           static_cast<uint8_t*>(scale_output),
152	                           num_groups);
153	    } else if (dtype == 1) {
154	        hipLaunchKernelGGL((quant_mxfp4_even_kernel<1>), grid, block, 0, hip_stream,
155	                           static_cast<const uint16_t*>(input),
156	                           static_cast<uint8_t*>(packed_output),
157	                           static_cast<uint8_t*>(scale_output),
158	                           num_groups);
159	    } else {
160	        return static_cast<int>(hipErrorInvalidValue);
161	    }
162	    return static_cast<int>(hipGetLastError());
163	}
